  if(action.confirmation){if(!actionForm.confirmationRef?.trim()||!actionForm.confirmationDate)return toast('填写已批准转正事件和生效日期','warning');patch={confirmationRef:actionForm.confirmationRef,confirmationDate:actionForm.confirmationDate};}
