  if(action.match){if(!current.allocations?.length||current.allocations.some(row=>toCents(row.allocated)>toCents(row.capacity))||current.allocations.reduce((sum,row)=>sum+(toCents(row.allocated)||0),0)!==toCents(current.amount))return toast('来源容量和分摊合计必须守恒，请补全分摊资料','warning');patch={matchedCents:toCents(current.amount),matchingVersion:(current.matchingVersion||0)+1,allocationSnapshot:clone(current.allocations),result:'按 '+current.allocations.length+' 个来源分摊 '+current.amount+' '+current.unit};}
  if(moduleId==='M24'&&current.status==='已匹配'&&next==='待匹配')patch={matchedCents:0,allocationSnapshot:[],result:'本次分摊已撤销，演示来源容量恢复；钱包未扣款'};
  if(action.calculate)patch={calculatedCents:Math.round(toCents(current.amount)*Number(current.rate)/100),result:'演示计算结果，不代表公司已发布的真实提成政策'};
  if(action.ratio){if(Number(current.basis)===0)return toast('基数为零，没有可计算的达成率','warning');patch={result:'演示达成率 '+(Number(current.actual)/Number(current.basis)*100).toFixed(2)+'%'};}
  if(action.material){if(Number(current.valid)>Number(current.total))return toast('有效量不得超过总量','warning');patch={result:current.mode==='范围替换'?'替换范围：'+current.replaceScope+'；原 '+current.existingCount+' 条 → 新 '+current.total+' 条；原批次保留':'演示新增 '+current.total+' 条；不覆盖旧期间',ratio:Number(current.total)?(Number(current.valid)/Number(current.total)*100).toFixed(1)+'%':'无有效基数'};}
  if(action.report){next=current.coverage==='存在缺口'?'有缺口':'可查看';patch={result:'产品：'+current.product+'；演示账户资料 '+(db.accounts?.filter(account=>current.product==='全部产品'||account.product===current.product).length||0)+' 条。'+(Number(current.basis)===0?'没有可比较基数。':''),reportAt:now()};}
  if(action.salary){const appointment=findPayrollAppointment(db.operations?.M29||[],current);if(!appointment)return toast('未找到该员工 ID、任职版本与期间的对应档案，请先在人事核实，不能按同名匹配','warning');patch={netCents:toCents(current.gross)-toCents(current.deduct),appointmentSnapshot:clone(appointment),result:'已匹配演示任职 '+appointment.appointmentRef+'；实发为应发减应扣（演示）'};}
  if(moduleId==='M31'&&next==='已确认')patch={...patch,confirmedBy:session.name};
